import math


class TokenBucket:
    def __init__(self, capacity, refill_rate, clock):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        if refill_rate < 0:
            raise ValueError("refill_rate must be non-negative")

        self._capacity = capacity
        self._refill_rate = refill_rate
        self._clock = clock
        self._tokens = capacity
        self._reference_time = clock()

    def _refill(self):
        now = self._clock()
        if now > self._reference_time:
            self._tokens = min(
                self._capacity,
                self._tokens + (now - self._reference_time) * self._refill_rate,
            )
            self._reference_time = now

    def _validate_n(self, n):
        if n <= 0:
            raise ValueError("n must be positive")
        if n > self._capacity:
            raise ValueError("n cannot exceed capacity")

    @property
    def tokens(self):
        self._refill()
        return self._tokens

    def try_consume(self, n=1):
        self._validate_n(n)
        self._refill()
        if self._tokens >= n:
            self._tokens -= n
            return True
        return False

    def wait_time(self, n=1):
        self._validate_n(n)
        self._refill()
        if self._tokens >= n:
            return 0.0
        if self._refill_rate == 0:
            return math.inf
        return (n - self._tokens) / self._refill_rate
