from decimal import Decimal, ROUND_HALF_UP
import re


class InsufficientFunds(Exception):
    pass


class Ledger:
    _VALID_AMOUNT = re.compile(r'^[0-9]+(?:\.[0-9]{1,2})?$')

    def __init__(self, overdraft_limit='0.00'):
        self._overdraft_limit = self._parse_amount(overdraft_limit, allow_zero=True)
        self._balance = Decimal('0.00')
        self._history = []

    @staticmethod
    def _parse_amount(amount, allow_zero=False):
        if not isinstance(amount, str):
            raise TypeError("amount must be a string")
        if not Ledger._VALID_AMOUNT.match(amount):
            raise ValueError("invalid amount format")
        value = Decimal(amount)
        if not allow_zero and value == 0:
            raise ValueError("amount must be non-zero")
        return value.quantize(Decimal('0.01'))

    def deposit(self, amount):
        value = self._parse_amount(amount)
        self._balance += value
        self._history.append(('deposit', self._format(value)))

    def withdraw(self, amount):
        value = self._parse_amount(amount)
        new_balance = self._balance - value
        if new_balance < -self._overdraft_limit:
            raise InsufficientFunds("withdrawal would exceed overdraft limit")
        self._balance = new_balance
        self._history.append(('withdraw', self._format(value)))
        if self._balance < 0:
            fee = Decimal('1.50')
            self._balance -= fee
            self._history.append(('fee', self._format(fee)))

    def balance(self):
        return self._format(self._balance)

    def history(self):
        return list(self._history)

    @staticmethod
    def _format(value):
        return str(value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
