def render(template, values):
    import re

    KEY_RE = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')
    SPACE = ' '

    n = len(template)
    out = []
    i = 0

    def is_space(c):
        return c == SPACE

    def strip_spaces(s):
        start = 0
        while start < len(s) and is_space(s[start]):
            start += 1
        end = len(s)
        while end > start and is_space(s[end - 1]):
            end -= 1
        return s[start:end]

    def validate_key(key):
        stripped = strip_spaces(key)
        if not stripped:
            raise ValueError(f"bad key: {stripped}")
        parts = stripped.split('.')
        for part in parts:
            if not KEY_RE.match(part):
                raise ValueError(f"bad key: {stripped}")
        return stripped

    def lookup(key):
        parts = key.split('.')
        cur = values
        for part in parts:
            if not isinstance(cur, dict) or part not in cur:
                return (None, True)
            cur = cur[part]
        if cur is None:
            return (None, True)
        return (cur, False)

    def format_value(val):
        if val is True:
            return "true"
        if val is False:
            return "false"
        return str(val)

    while i < n:
        c = template[i]
        if c == '\\':
            if i + 1 < n:
                nxt = template[i + 1]
                if nxt == '\\':
                    out.append('\\')
                    i += 2
                    continue
                if nxt == '{':
                    out.append('{')
                    i += 2
                    continue
                # 其他字符：反斜杠原样输出，后面字符照常处理
                out.append('\\')
                i += 1
                continue
            else:
                out.append('\\')
                i += 1
                continue
        elif c == '{':
            if i + 1 < n and template[i + 1] == '{':
                # 占位符开始
                start = i
                i += 2
                # 找到下一个 }}
                end = template.find('}}', i)
                if end == -1:
                    raise ValueError(f"unclosed placeholder at {start}")
                content = template[i:end]
                # 拆分键和默认值，只在第一个 | 处分开
                pipe_idx = content.find('|')
                if pipe_idx == -1:
                    key_part = content
                    default_part = None
                else:
                    key_part = content[:pipe_idx]
                    default_part = content[pipe_idx + 1:]
                key = validate_key(key_part)
                val, missing = lookup(key)
                if missing:
                    if default_part is not None:
                        out.append(strip_spaces(default_part))
                    else:
                        raise KeyError(f"missing: {key}")
                else:
                    out.append(format_value(val))
                i = end + 2
                continue
            else:
                # 单个 { 原样输出
                out.append(c)
                i += 1
                continue
        else:
            out.append(c)
            i += 1
            continue

    return ''.join(out)
