def wrap_text(text, width):
    if not isinstance(width, int) or width < 2:
        raise ValueError("width must be an int >= 2")
    words = text.split()
    if not words:
        return []
    lines = []
    current = ""
    for word in words:
        if len(word) > width:
            # finish current line if any
            if current:
                lines.append(current)
                current = ""
            # cut long word
            chunk_len = width - 1
            while len(word) > width:
                lines.append(word[:chunk_len] + "-")
                word = word[chunk_len:]
            current = word
        else:
            # normal greedy append
            if current:
                candidate = current + " " + word
                if len(candidate) <= width:
                    current = candidate
                else:
                    lines.append(current)
                    current = word
            else:
                current = word
    if current:
        lines.append(current)
    return lines
