class CycleError(ValueError):
    def __init__(self, nodes):
        self.nodes = sorted(nodes)
        super().__init__(f"cycle detected involving nodes: {self.nodes}")


def _build_graph(nodes, edges):
    node_set = set(nodes)
    for before, after in edges:
        if before not in node_set:
            raise ValueError(f"unknown node: {before}")
        if after not in node_set:
            raise ValueError(f"unknown node: {after}")

    # adjacency: before -> set of afters
    adj = {node: set() for node in node_set}
    # in_degree: node -> number of distinct predecessors
    in_degree = {node: 0 for node in node_set}
    seen_edges = set()
    for before, after in edges:
        if before == after:
            # self-loop is still an edge; count it once
            if (before, after) not in seen_edges:
                seen_edges.add((before, after))
                adj[before].add(after)
                in_degree[after] += 1
            continue
        if (before, after) not in seen_edges:
            seen_edges.add((before, after))
            adj[before].add(after)
            in_degree[after] += 1

    return node_set, adj, in_degree


def topo_order(nodes, edges):
    node_set, adj, in_degree = _build_graph(nodes, edges)

    result = []
    available = sorted([node for node in node_set if in_degree[node] == 0])
    placed = set()
    in_degree = dict(in_degree)

    while available:
        node = available.pop(0)
        result.append(node)
        placed.add(node)

        for after in sorted(adj[node]):
            in_degree[after] -= 1
            if in_degree[after] == 0:
                # insert maintaining sorted order
                inserted = False
                for i, existing in enumerate(available):
                    if after < existing:
                        available.insert(i, after)
                        inserted = True
                        break
                if not inserted:
                    available.append(after)

    if len(result) != len(node_set):
        unplaced = node_set - placed
        raise CycleError(unplaced)

    return result


def layers(nodes, edges):
    node_set, adj, in_degree = _build_graph(nodes, edges)

    result = []
    remaining = set(node_set)
    in_degree = dict(in_degree)

    while remaining:
        layer = [node for node in remaining if in_degree[node] == 0]
        if not layer:
            raise CycleError(remaining)
        layer.sort()
        result.append(layer)
        for node in layer:
            remaining.remove(node)
            for after in adj[node]:
                in_degree[after] -= 1

    return result
