def spans(prices):
    if not isinstance(prices, list):
        raise TypeError("prices must be a list")
    n = len(prices)
    result = [0] * n
    stack = []  # stores indices with increasing (or equal) prices, skipping None barriers
    for i in range(n):
        p = prices[i]
        if p is None:
            result[i] = 0
            stack.clear()
            continue
        if isinstance(p, bool) or not isinstance(p, (int, float)):
            raise TypeError("price must be int, float, or None")
        while stack and prices[stack[-1]] > p:
            stack.pop()
        if stack:
            result[i] = i - stack[-1]
        else:
            result[i] = i + 1
        stack.append(i)
    return result


def next_greater(prices):
    if not isinstance(prices, list):
        raise TypeError("prices must be a list")
    n = len(prices)
    result = [-1] * n
    # We scan right-to-left. We need, for each i, the nearest j>i with price > p_i
    # and no None in between. A None resets everything to its right as inaccessible.
    # Maintain a monotonic decreasing stack of candidate indices (prices decreasing)
    # so that the top is the nearest greater element.
    stack = []  # indices with decreasing prices from right to left
    for i in range(n - 1, -1, -1):
        p = prices[i]
        if p is None:
            result[i] = -1
            stack.clear()
            continue
        if isinstance(p, bool) or not isinstance(p, (int, float)):
            raise TypeError("price must be int, float, or None")
        # pop elements that are not greater than p (<= p or equal)
        while stack and prices[stack[-1]] <= p:
            stack.pop()
        if stack:
            result[i] = stack[-1]
        else:
            result[i] = -1
        stack.append(i)
    return result


def widest_span(prices):
    span_list = spans(prices)
    best_idx = -1
    best_span = 0
    for i, s in enumerate(span_list):
        if s >= best_span:
            best_span = s
            best_idx = i
    return (best_idx, best_span)
