from __future__ import annotations

import re
from collections import deque
from decimal import Decimal, ROUND_HALF_EVEN


class FifoBook:
    _PRICE_RE = re.compile(r'^[0-9]+(?:\.[0-9]{1,4})?$')

    def __init__(self) -> None:
        self._lots: deque[tuple[int, str, Decimal]] = deque()
        self._total_qty: int = 0
        self._realized: Decimal = Decimal("0.00")

    @staticmethod
    def _validate_qty(qty: int) -> None:
        if type(qty) is not int:
            raise TypeError("qty must be int")
        if qty <= 0:
            raise ValueError("qty must be positive")

    @staticmethod
    def _validate_price(price: str) -> Decimal:
        if type(price) is not str:
            raise TypeError("price must be str")
        if not FifoBook._PRICE_RE.match(price):
            raise ValueError("invalid price format")
        return Decimal(price)

    def buy(self, qty: int, price: str) -> None:
        self._validate_qty(qty)
        dec_price = self._validate_price(price)
        self._lots.append((qty, price, dec_price))
        self._total_qty += qty

    def sell(self, qty: int, price: str) -> Decimal:
        self._validate_qty(qty)
        sell_price = self._validate_price(price)
        if qty > self._total_qty:
            raise ValueError("insufficient holdings")

        remaining = qty
        realized_sum = Decimal("0")
        while remaining > 0:
            lot_qty, lot_price_str, lot_price = self._lots[0]
            take = lot_qty if lot_qty <= remaining else remaining
            realized_sum += (sell_price - lot_price) * take
            if take == lot_qty:
                self._lots.popleft()
            else:
                self._lots[0] = (lot_qty - take, lot_price_str, lot_price)
            remaining -= take
            self._total_qty -= take

        quantized = realized_sum.quantize(Decimal("0.01"), rounding=ROUND_HALF_EVEN)
        self._realized += quantized
        return quantized

    def realized(self) -> Decimal:
        return self._realized

    def holdings(self) -> int:
        return self._total_qty

    def lots(self) -> list[tuple[int, str]]:
        return [(qty, price_str) for qty, price_str, _ in self._lots]

    def cost_basis(self) -> Decimal:
        total = Decimal("0")
        for qty, _, price in self._lots:
            total += price * qty
        return total.quantize(Decimal("0.01"), rounding=ROUND_HALF_EVEN)
