import re


_VERSION_RE = re.compile(
    r"^[vV]?(?P<major>0|[1-9]\d*)\.(?P<minor>0|[1-9]\d*)\.(?P<patch>0|[1-9]\d*)"
    r"(?:-(?P<prerelease>[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+(?P<build>[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$"
)


def parse_version(text):
    if not isinstance(text, str):
        raise ValueError("invalid version: input must be a string")

    match = _VERSION_RE.match(text)
    if match is None:
        raise ValueError("invalid version: malformed version string")

    major = int(match.group("major"))
    minor = int(match.group("minor"))
    patch = int(match.group("patch"))

    prerelease_raw = match.group("prerelease")
    prerelease = ()
    if prerelease_raw is not None:
        parsed = []
        for ident in prerelease_raw.split("."):
            if ident == "":
                raise ValueError("invalid version: empty prerelease identifier")
            if ident.isdigit():
                if ident[0] == "0" and len(ident) > 1:
                    raise ValueError(
                        "invalid version: numeric prerelease identifier has leading zero"
                    )
                parsed.append(int(ident))
            else:
                if not all(ch.isascii() and (ch.isalnum() or ch == "-") for ch in ident):
                    raise ValueError(
                        "invalid version: prerelease identifier contains invalid characters"
                    )
                parsed.append(ident)
        prerelease = tuple(parsed)

    build = match.group("build")
    if build is not None:
        if any(ident == "" for ident in build.split(".")):
            raise ValueError("invalid version: empty build identifier")

    return (major, minor, patch, prerelease, build)


def _compare_prerelease(a, b):
    # A version without a prerelease ranks higher than one with a prerelease.
    if a == () and b == ():
        return 0
    if a == ():
        return 1
    if b == ():
        return -1

    for x, y in zip(a, b):
        x_num = isinstance(x, int)
        y_num = isinstance(y, int)
        if x_num and y_num:
            if x < y:
                return -1
            if x > y:
                return 1
        elif x_num:
            return -1
        elif y_num:
            return 1
        else:
            if x < y:
                return -1
            if x > y:
                return 1
    if len(a) < len(b):
        return -1
    if len(a) > len(b):
        return 1
    return 0


def compare_versions(a, b):
    a_parsed = parse_version(a)
    b_parsed = parse_version(b)

    for key in (0, 1, 2):  # major, minor, patch
        if a_parsed[key] < b_parsed[key]:
            return -1
        if a_parsed[key] > b_parsed[key]:
            return 1

    cmp = _compare_prerelease(a_parsed[3], b_parsed[3])
    if cmp != 0:
        return cmp

    return 0


def sort_versions(versions):
    return sorted(versions, key=cmp_to_key(compare_versions))
