import heapq
from typing import Any


class MedianTracker:
    def __init__(self, prefer_high: bool = False) -> None:
        self.prefer_high = prefer_high
        # max-heap for the lower half (store negatives)
        self.low: list[int] = []
        # min-heap for the upper half
        self.high: list[int] = []
        # multiset counts for delayed deletion
        self.delayed_low: dict[int, int] = {}
        self.delayed_high: dict[int, int] = {}
        self.low_size = 0  # effective size of low half
        self.high_size = 0  # effective size of high half

    def _validate(self, x: Any) -> int:
        if isinstance(x, bool) or not isinstance(x, int):
            raise TypeError("value must be int")
        return x

    def _prune(self, heap: list[int], delayed: dict[int, int], size_attr: str) -> None:
        while heap:
            num = -heap[0] if size_attr == "low" else heap[0]
            if delayed.get(num, 0):
                heapq.heappop(heap)
                delayed[num] -= 1
                if delayed[num] == 0:
                    del delayed[num]
            else:
                break

    def _make_balance(self) -> None:
        # Ensure low has at least as many as high, and at most one more
        if self.low_size > self.high_size + 1:
            self._prune(self.low, self.delayed_low, "low")
            moved = -heapq.heappop(self.low)
            self.low_size -= 1
            heapq.heappush(self.high, moved)
            self.high_size += 1
            self._prune(self.low, self.delayed_low, "low")
        elif self.low_size < self.high_size:
            self._prune(self.high, self.delayed_high, "high")
            moved = heapq.heappop(self.high)
            self.high_size -= 1
            heapq.heappush(self.low, -moved)
            self.low_size += 1
            self._prune(self.high, self.delayed_high, "high")

    def add(self, x: Any) -> None:
        x = self._validate(x)

        if not self.low or x <= -self.low[0]:
            heapq.heappush(self.low, -x)
            self.low_size += 1
        else:
            heapq.heappush(self.high, x)
            self.high_size += 1

        self._make_balance()

    def remove(self, x: Any) -> None:
        x = self._validate(x)

        # Determine which half x belongs to
        if self.low_size == 0 and self.high_size == 0:
            raise ValueError("not present")

        self._prune(self.low, self.delayed_low, "low")
        self._prune(self.high, self.delayed_high, "high")

        low_max = -self.low[0] if self.low else None

        if low_max is not None and x <= low_max:
            # x should be in low
            if x == low_max:
                heapq.heappop(self.low)
                self._prune(self.low, self.delayed_low, "low")
            else:
                self.delayed_low[x] = self.delayed_low.get(x, 0) + 1
            self.low_size -= 1
        else:
            # x should be in high
            if self.high and x == self.high[0]:
                heapq.heappop(self.high)
                self._prune(self.high, self.delayed_high, "high")
            else:
                self.delayed_high[x] = self.delayed_high.get(x, 0) + 1
            self.high_size -= 1

        self._make_balance()

    def median(self) -> int:
        if self.low_size == 0 and self.high_size == 0:
            raise LookupError("median of empty MedianTracker")

        self._prune(self.low, self.delayed_low, "low")
        self._prune(self.high, self.delayed_high, "high")

        if (self.low_size + self.high_size) % 2 == 1:
            return -self.low[0]
        if self.prefer_high:
            return self.high[0]
        return -self.low[0]

    def __len__(self) -> int:
        return self.low_size + self.high_size
