def compress(data: bytes) -> bytes:
    if not data:
        return b""
    # Non-empty input: prefix a single byte that cannot appear in original data,
    # then return the payload unchanged. Since every byte 0..255 may appear in data,
    # we first escape all occurrences of the chosen marker byte.
    marker = 0xFF
    escaped = data.replace(bytes([marker]), bytes([marker, marker]))
    return bytes([marker]) + escaped


def decompress(blob: bytes) -> bytes:
    if not blob:
        return b""
    if blob[0] != 0xFF:
        raise ValueError("invalid compressed blob")
    payload = blob[1:]
    # Unescape: each doubled marker represents one literal marker byte.
    return payload.replace(bytes([0xFF, 0xFF]), bytes([0xFF]))
