def merge(intervals):
    """
    Return a sorted list of disjoint half-open intervals covering the same points.
    Overlapping or touching intervals are merged. Empty intervals are dropped.
    Intervals with start > end raise ValueError. Inputs are not modified.
    """
    cleaned = []
    for iv in intervals:
        start, end = iv
        if start > end:
            raise ValueError("interval start must not be greater than end")
        if start == end:
            continue
        cleaned.append((start, end))
    if not cleaned:
        return []
    cleaned.sort(key=lambda x: x[0])
    merged = [cleaned[0]]
    for start, end in cleaned[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            if end > last_end:
                merged[-1] = (last_start, end)
        else:
            merged.append((start, end))
    return merged


def subtract(a, b):
    """
    Return the points in interval list a that are not in interval list b.
    Result is a merged, sorted list of half-open intervals. Inputs may be
    unsorted, overlapping or touching. Inputs are not modified.
    """
    a = merge(a)
    b = merge(b)
    if not a:
        return []
    if not b:
        return a
    result = []
    i = 0
    start, end = a[0]
    for b_start, b_end in b:
        while i < len(a):
            a_start, a_end = a[i]
            if a_end <= b_start:
                result.append((a_start, a_end))
                i += 1
                if i < len(a):
                    start, end = a[i]
                continue
            if a_start >= b_end:
                break
            if a_start < b_start:
                result.append((a_start, b_start))
            if a_end > b_end:
                start = b_end
                end = a_end
                break
            else:
                i += 1
                if i < len(a):
                    start, end = a[i]
    if i < len(a):
        result.append((start, end))
        result.extend(a[i + 1:])
    return result


def total_length(intervals):
    """
    Return the total length covered by the union of the half-open intervals.
    Returns 0 if there are no intervals.
    """
    merged = merge(intervals)
    total = 0
    for start, end in merged:
        total += end - start
    return total
