def validate_stream(events):
    seen_ids = set()
    for ts, eid, payload in events:
        if eid in seen_ids:
            raise ValueError(f"duplicate id: {eid}")
        seen_ids.add(eid)

    prev = None
    for ts, eid, payload in events:
        key = (ts, eid)
        if prev is not None and key <= prev:
            raise ValueError(f"unsorted: {key} after {prev}")
        prev = key

    return None


def diff_events(old, new):
    validate_stream(old)
    validate_stream(new)

    old_ids = [eid for ts, eid, payload in old]
    new_ids = [eid for ts, eid, payload in new]

    old_set = set(old_ids)
    new_set = set(new_ids)

    added = [eid for eid in new_ids if eid not in old_set]
    removed = [eid for eid in old_ids if eid not in new_set]

    old_map = {eid: (ts, payload) for ts, eid, payload in old}

    moved = []
    changed = []
    for ts, eid, payload in new:
        if eid in old_set:
            old_ts, old_payload = old_map[eid]
            if ts != old_ts:
                moved.append(eid)
            if payload != old_payload:
                changed.append(eid)

    return {
        'added': added,
        'removed': removed,
        'moved': moved,
        'changed': changed,
    }


def merge_streams(a, b):
    validate_stream(a)
    validate_stream(b)

    a_map = {eid: (ts, payload) for ts, eid, payload in a}

    merged = list(a)
    for ts, eid, payload in b:
        if eid in a_map:
            for i, (ats, aeid, apayload) in enumerate(merged):
                if aeid == eid:
                    merged[i] = (ts, eid, payload)
                    break
        else:
            merged.append((ts, eid, payload))

    merged.sort(key=lambda event: (event[0], event[1]))

    prev = None
    for ts, eid, payload in merged:
        key = (ts, eid)
        if prev is not None and key <= prev:
            raise ValueError(f"unsorted merge: {key} after {prev}")
        prev = key

    return merged
