import copy


def escape_token(token):
    return token.replace('~', '~0').replace('/', '~1')


def _decode_pointer(pointer):
    if pointer == '':
        return []
    if not pointer.startswith('/'):
        raise ValueError("Non-empty pointer must start with '/'")
    tokens = pointer[1:].split('/')
    decoded = []
    for token in tokens:
        result = []
        i = 0
        while i < len(token):
            ch = token[i]
            if ch == '~':
                if i + 1 >= len(token):
                    raise ValueError("Unescaped '~' at end of token")
                nxt = token[i + 1]
                if nxt == '0':
                    result.append('~')
                    i += 2
                elif nxt == '1':
                    result.append('/')
                    i += 2
                else:
                    raise ValueError("Invalid escape sequence in token")
            else:
                result.append(ch)
                i += 1
        decoded.append(''.join(result))
    return decoded


def resolve(doc, pointer):
    tokens = _decode_pointer(pointer)
    current = doc
    for token in tokens:
        if isinstance(current, dict):
            if token not in current:
                raise KeyError(token)
            current = current[token]
        elif isinstance(current, list):
            if token == '-':
                raise KeyError(token)
            if token == '0':
                index = 0
            else:
                if not token.isdigit() or token[0] == '0':
                    raise KeyError(token)
                index = int(token)
                if index >= len(current):
                    raise KeyError(token)
            current = current[index]
        else:
            raise KeyError(token)
    return current


def set_value(doc, pointer, value):
    new_doc = copy.deepcopy(doc)
    if pointer == '':
        return value
    tokens = _decode_pointer(pointer)
    parent_tokens = tokens[:-1]
    last_token = tokens[-1]
    current = new_doc
    for token in parent_tokens:
        if isinstance(current, dict):
            if token not in current:
                raise KeyError(token)
            current = current[token]
        elif isinstance(current, list):
            if token == '-':
                raise KeyError(token)
            if token == '0':
                index = 0
            else:
                if not token.isdigit() or token[0] == '0':
                    raise KeyError(token)
                index = int(token)
                if index >= len(current):
                    raise KeyError(token)
            current = current[index]
        else:
            raise KeyError(token)
    if isinstance(current, dict):
        current[last_token] = value
    elif isinstance(current, list):
        if last_token == '-':
            current.append(value)
        elif last_token == '0':
            current[0] = value
        else:
            if not last_token.isdigit() or last_token[0] == '0':
                raise KeyError(last_token)
            index = int(last_token)
            if index > len(current):
                raise KeyError(last_token)
            if index == len(current):
                current.append(value)
            else:
                current[index] = value
    else:
        raise KeyError(last_token)
    return new_doc
