class Scheduler:
    def __init__(self):
        self._tasks = {}  # name -> (priority, after_set, state, add_order)
        self._order_counter = 0

    def add(self, name, priority, after=()):
        if name in self._tasks:
            raise ValueError(f"Task {name!r} already added")
        after_set = set()
        for dep in after:
            if dep not in self._tasks:
                raise KeyError(f"Dependency {dep!r} not found")
            after_set.add(dep)
        self._tasks[name] = [priority, after_set, "pending", self._order_counter]
        self._order_counter += 1

    def next(self):
        ready = []
        for name, (priority, after_set, state, add_order) in self._tasks.items():
            if state != "pending":
                continue
            completed = self._completed_set()
            if after_set.issubset(completed):
                ready.append((-priority, add_order, name))
        if not ready:
            return None
        ready.sort()
        _, _, name = ready[0]
        self._tasks[name][2] = "running"
        return name

    def _completed_set(self):
        return {name for name, task in self._tasks.items() if task[2] == "completed"}

    def complete(self, name):
        if name not in self._tasks:
            raise KeyError(f"Task {name!r} not found")
        state = self._tasks[name][2]
        if state != "running":
            raise ValueError(f"Task {name!r} is not running")
        self._tasks[name][2] = "completed"

    def remaining(self):
        return sum(1 for task in self._tasks.values() if task[2] != "completed")
