def _validate_intervals(intervals):
    if not isinstance(intervals, list):
        raise TypeError("intervals must be a list")
    for item in intervals:
        if not isinstance(item, tuple) or len(item) != 3:
            raise TypeError("each interval must be a 3-tuple")
        start, end, weight = item
        for value, name in ((start, "start"), (end, "end"), (weight, "weight")):
            if isinstance(value, bool) or not isinstance(value, int):
                raise TypeError(f"{name} must be int (not bool or float)")
        if start >= end:
            raise ValueError("start must be less than end")


def best_schedule(intervals):
    _validate_intervals(intervals)

    # Filter positive-weight intervals and sort by end.
    # Non-positive intervals are never chosen per tie-breaking rule.
    filtered = [(s, e, w) for s, e, w in intervals if w > 0]
    if not filtered:
        return (0, 0)

    filtered.sort(key=lambda x: x[1])

    starts = [s for s, e, w in filtered]
    ends = [e for s, e, w in filtered]
    weights = [w for s, e, w in filtered]
    n = len(filtered)

    # dp[i] = best (total_weight, -count) using intervals among filtered[0..i-1]
    # with the i-th interval considered as ending at ends[i-1].
    # We store negative count so that max() naturally prefers fewer intervals
    # when weights are equal.
    from bisect import bisect_right

    dp = [(0, 0)] * (n + 1)
    for i in range(1, n + 1):
        s, e, w = filtered[i - 1]
        # Find the last interval that ends <= s (non-overlapping with [s, e))
        j = bisect_right(ends, s, 0, i - 1)
        prev_weight, prev_neg_count = dp[j]
        cand_weight = prev_weight + w
        cand_neg_count = prev_neg_count - 1
        # Compare with not taking interval i-1
        if (cand_weight, cand_neg_count) > dp[i - 1]:
            dp[i] = (cand_weight, cand_neg_count)
        else:
            dp[i] = dp[i - 1]

    total_weight, neg_count = dp[n]
    return (total_weight, -neg_count)


def max_parallel(intervals):
    _validate_intervals(intervals)

    events = []
    for s, e, w in intervals:
        events.append((s, 1))
        events.append((e, -1))

    events.sort()
    current = 0
    max_count = 0
    for _, delta in events:
        current += delta
        if current > max_count:
            max_count = current
    return max_count
