    for value, numeral in zip(values, numerals):
        while n >= value:
            result.append(numeral)
            n -= value
    return "".join(result)


def from_roman(s):
    if type(s) is not str:
        raise TypeError("s must be a str")
    if not s:
        raise ValueError("empty string is not a valid Roman numeral")

    # Build the canonical numeral and compare for exact form.
    total = 0
    i = 0
    values = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    length = len(s)
    while i < length:
        current = s[i]
        if current not in values:
            raise ValueError("invalid character in Roman numeral")
        if i + 1 < length:
            next_char = s[i + 1]
            if next_char not in values:
                raise ValueError("invalid character in Roman numeral")
            if values[current] < values[next_char]:
                # Subtractive pair
                pair = current + next_char
                if pair not in ("IV", "IX", "XL", "XC", "CD", "CM"):
                    raise ValueError("invalid subtractive form")
                total += values[next_char] - values[current]
                i += 2
            else:
                total += values[current]
                i += 1
        else:
            total += values[current]
            i += 1

    if total < 1 or total > 3999:
        raise ValueError("value out of range")

    canonical = to_roman(total)
    if s != canonical:
        raise ValueError("non-canonical Roman numeral")

    return total


def is_roman(s):
    try:
        from_roman(s)
        return True
    except (TypeError, ValueError):
