from fractions import Fraction

def evaluate(expr):
    if not isinstance(expr, str):
        raise ValueError("Input must be a string")
    s = expr
    n = len(s)
    pos = 0

    def skip_ws():
        nonlocal pos
        while pos < n and s[pos] in ' \t':
            pos += 1

    def peek():
        skip_ws()
        if pos < n:
            return s[pos]
        return None

    def consume(expected=None):
        skip_ws()
        if pos >= n:
            raise ValueError("Unexpected end of input")
        ch = s[pos]
        if expected is not None and ch != expected:
            raise ValueError(f"Expected {expected!r} at position {pos}")
        pos += 1
        return ch

    def parse_integer():
        skip_ws()
        start = pos
        if pos >= n or not s[pos].isdigit():
            raise ValueError(f"Expected integer at position {pos}")
        while pos < n and s[pos].isdigit():
            pos += 1
        return int(s[start:pos])

    def parse_atom():
        skip_ws()
        if pos >= n:
            raise ValueError("Unexpected end of input")
        ch = s[pos]
        if ch == '(':
            consume('(')
            val = parse_expr()
            skip_ws()
            if pos >= n or s[pos] != ')':
                raise ValueError("Missing closing parenthesis")
            consume(')')
            return val
        elif ch.isdigit():
            return Fraction(parse_integer())
        else:
            raise ValueError(f"Unexpected character {ch!r} at position {pos}")

    def parse_power():
        base = parse_atom()
        skip_ws()
        if pos < n and s[pos] == '^':
            consume('^')
            exp = parse_unary()
            if exp.denominator != 1:
                raise ValueError("Exponent must be a whole number")
            exp_int = exp.numerator
            if base == 0:
                if exp_int < 0:
                    raise ZeroDivisionError("0 cannot be raised to a negative power")
                if exp_int == 0:
                    return Fraction(1, 1)
                return Fraction(0, 1)
            # Compute exact power using Fractions
            result = Fraction(1, 1)
            b = base
            e = exp_int
            if e < 0:
                b = Fraction(1, 1) / b
                e = -e
            while e > 0:
                if e & 1:
                    result *= b
                b *= b
                e >>= 1
            return result
        return base

    def parse_unary():
        skip_ws()
        if pos < n and s[pos] == '-':
            consume('-')
            val = parse_unary()
            return -val
        return parse_power()

    def parse_term():
        val = parse_unary()
        while True:
            skip_ws()
            if pos >= n or s[pos] not in ('*', '/'):
                break
            op = consume()
            rhs = parse_unary()
            if op == '*':
                val *= rhs
            else:
                val /= rhs
        return val

    def parse_expr():
        val = parse_term()
        while True:
            skip_ws()
            if pos >= n or s[pos] not in ('+', '-'):
                break
            op = consume()
            rhs = parse_term()
            if op == '+':
                val += rhs
            else:
                val -= rhs
        return val

    # Reject empty or whitespace-only input
    skip_ws()
    if pos >= n:
        raise ValueError("Empty expression")

    result = parse_expr()

    # Ensure no leftover non-whitespace tokens
    skip_ws()
    if pos != n:
        raise ValueError(f"Unexpected trailing character {s[pos]!r} at position {pos}")

    # Return int if whole number, else Fraction
    if result.denominator == 1:
        return result.numerator
    return result
