def _parse_version(version):
    s = version.strip()
    if not s:
        raise ValueError("empty version")
    parts = s.split('.')
    result = []
    for part in parts:
        if not part:
            raise ValueError("empty version component")
        if not part.isdigit():
            raise ValueError("non-numeric version component")
        result.append(int(part))
    return result


def _normalize(a, b):
    n = max(len(a), len(b))
    return (
        a + [0] * (n - len(a)),
        b + [0] * (n - len(b)),
    )


def _compare(a, b):
    a, b = _normalize(a, b)
    for x, y in zip(a, b):
        if x < y:
            return -1
        if x > y:
            return 1
    return 0


def _format_version(parts):
    return '.'.join(str(p) for p in parts)


def _upper_bound_for_compatible(parts):
    if len(parts) == 1:
        raise ValueError("~= requires at least two components")
    upper = parts[:-1]
    upper[-1] += 1
    return upper


def _parse_clause(clause):
    s = clause.strip()
    if not s:
        raise ValueError("empty clause")
    operators = ('==', '!=', '>=', '<=', '~=', '>', '<')
    op = None
    for candidate in operators:
        if s.startswith(candidate):
            op = candidate
            version_str = s[len(candidate):].strip()
            break
    if op is None:
        raise ValueError("missing operator")
    version = _parse_version(version_str)
    return op, version


def _clause_to_ranges(op, version):
    if op == '==':
        return [(version, True, version, True)]
    if op == '!=':
        return [
            (None, True, version, False),
            (version, False, None, True),
        ]
    if op == '>=':
        return [(version, True, None, True)]
    if op == '<=':
        return [(None, True, version, True)]
    if op == '>':
        return [(version, False, None, True)]
    if op == '<':
        return [(None, True, version, False)]
    if op == '~=':
        upper = _upper_bound_for_compatible(version)
        return [(version, True, upper, False)]


def _in_range(version, low, low_inclusive, high, high_inclusive):
    if low is not None:
        cmp = _compare(version, low)
        if cmp < 0 or (cmp == 0 and not low_inclusive):
            return False
    if high is not None:
        cmp = _compare(version, high)
        if cmp > 0 or (cmp == 0 and not high_inclusive):
            return False
    return True


def satisfies(version, spec):
    version_parts = _parse_version(version)
    spec = spec.strip()
    if not spec:
        return True
    ranges = []
    for clause in spec.split(','):
        op, v = _parse_clause(clause)
        ranges.extend(_clause_to_ranges(op, v))
    for low, low_inc, high, high_inc in ranges:
        if not _in_range(version_parts, low, low_inc, high, high_inc):
            return False
    return True


def max_satisfying(versions, spec):
    best = None
    best_index = None
    for index, v in enumerate(versions):
        parts = _parse_version(v)
        if satisfies(v, spec):
            if best is None or _compare(parts, best) > 0 or (
                _compare(parts, best) == 0 and index < best_index
            ):
                best = parts
                best_index = index
    if best is None:
        return None
    return versions[best_index]
