from collections import deque
from math import isnan


def _validate_limit(limit):
    if isinstance(limit, bool) or not isinstance(limit, (int, float)):
        raise ValueError("limit must be an int or float")
    if isnan(limit):
        raise ValueError("limit must not be NaN")
    if limit < 0:
        raise ValueError("limit must be >= 0")


def _validate_value(x):
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise TypeError("every element of values must be an int or float")
    if isinstance(x, float) and isnan(x):
        raise ValueError("values must not contain NaN")


def longest_calm(values, limit):
    _validate_limit(limit)

    n = len(values)
    if n == 0:
        return (0, 0)

    for x in values:
        _validate_value(x)

    max_deque = deque()
    min_deque = deque()
    left = 0
    best_len = 0
    best_i = 0

    for right in range(n):
        x = values[right]
        while max_deque and values[max_deque[-1]] <= x:
            max_deque.pop()
        max_deque.append(right)
        while min_deque and values[min_deque[-1]] >= x:
            min_deque.pop()
        min_deque.append(right)

        while (
            max_deque
            and min_deque
            and values[max_deque[0]] - values[min_deque[0]] > limit
        ):
            if max_deque[0] == left:
                max_deque.popleft()
            if min_deque[0] == left:
                min_deque.popleft()
            left += 1

        window_len = right - left + 1
        if window_len > best_len:
            best_len = window_len
            best_i = left

    return (best_i, best_i + best_len)


def count_calm(values, limit):
    _validate_limit(limit)

    n = len(values)
    if n == 0:
        return 0

    for x in values:
        _validate_value(x)

    max_deque = deque()
    min_deque = deque()
    left = 0
    total = 0

    for right in range(n):
        x = values[right]
        while max_deque and values[max_deque[-1]] <= x:
            max_deque.pop()
        max_deque.append(right)
        while min_deque and values[min_deque[-1]] >= x:
            min_deque.pop()
        min_deque.append(right)

        while (
            max_deque
            and min_deque
            and values[max_deque[0]] - values[min_deque[0]] > limit
        ):
            if max_deque[0] == left:
                max_deque.popleft()
            if min_deque[0] == left:
                min_deque.popleft()
            left += 1

        total += right - left + 1

    return total
